const tasksRaw = $json.results || [];

// 1. Estrai eventi Google Calendar di oggi
let calRaw = [];
try {
  calRaw = $('Get Today Calendar Events').all() || [];
} catch(e) {
  calRaw = [];
}

const calendarEvents = [];
for (const e of calRaw) {
  const j = e.json || {};
  if (!j.summary) continue;

  const startRaw = j.start?.dateTime || j.start?.date || '';
  const endRaw = j.end?.dateTime || j.end?.date || '';
  let timeStr = '';
  if (startRaw.includes('T')) {
    const s = new Date(startRaw).toLocaleTimeString('it-IT', { timeZone: 'Europe/Rome', hour: '2-digit', minute: '2-digit' });
    const en = endRaw.includes('T') ? new Date(endRaw).toLocaleTimeString('it-IT', { timeZone: 'Europe/Rome', hour: '2-digit', minute: '2-digit' }) : '';
    timeStr = en ? `${s} - ${en}` : s;
  } else {
    timeStr = 'Tutto il giorno';
  }

  const loc = j.location ? ` (${j.location})` : '';
  calendarEvents.push(`• ⏰ *${timeStr}*: ${j.summary}${loc}`);
}

const items = [];

// Header Messaggio Buongiorno con Calendario
let introText = `☀️ *Buongiorno Angelo!*\nEcco il tuo briefing quotidiano del Second Brain.\n\n`;

if (calendarEvents.length > 0) {
  introText += `📅 *I tuoi impegni di oggi in Calendario:*\n` + calendarEvents.join('\n') + `\n\n`;
} else {
  introText += `📅 *Nessun evento o lezione in calendario per oggi!* 🏖️\n\n`;
}

if (tasksRaw.length === 0) {
  introText += `🚀 *Nessun task in sospeso su Notion.* Il tuo piano è libero per progetti strategici o riposo!`;
  return [{
    json: {
      has_tasks: false,
      chat_id: Number($env.TELEGRAM_USER_ID),
      text: introText,
      reply_markup: { inline_keyboard: [] }
    }
  }];
} else {
  introText += `📋 *Hai ${tasksRaw.length} task da completare.* Eccoli di seguito con i pulsanti rapidi:`;
  items.push({
    json: {
      has_tasks: true,
      chat_id: Number($env.TELEGRAM_USER_ID),
      text: introText,
      reply_markup: { inline_keyboard: [] }
    }
  });
}

// Card per ciascun Task
for (let i = 0; i < tasksRaw.length; i++) {
  const task = tasksRaw[i];
  const pageId = task.id.replace(/-/g, '');
  const title = task.properties['Task Name']?.title[0]?.plain_text || 'Task senza nome';
  const priority = task.properties['Priority']?.select?.name || 'P3 - Normal';
  const dueDate = task.properties['Due Date']?.date?.start || 'Nessuna data';
  const source = task.properties['Source']?.select?.name || 'Manuale';

  let priorityEmoji = '🔵';
  if (priority.includes('Critical')) priorityEmoji = '🔴';
  else if (priority.includes('High')) priorityEmoji = '🟠';
  else if (priority.includes('Normal')) priorityEmoji = '🟡';

  const text = `${priorityEmoji} *Task ${i + 1}: ${title}*\n📅 Scadenza: ${dueDate}\n🏷️ Priorità: ${priority}\n📌 Fonte: ${source}`;

  items.push({
    json: {
      has_tasks: true,
      chat_id: Number($env.TELEGRAM_USER_ID),
      text,
      page_id: pageId,
      reply_markup: {
        inline_keyboard: [
          [
            {
              text: "✅ Segna come completato",
              callback_data: `done:${pageId}`
            }
          ]
        ]
      }
    }
  });
}

return items;
